1	/**
2	 * Main Cloudflare Worker entry point for the Paperclip API.
3	 *
4	 * This file:
5	 *   1. Creates a Hono app and mounts route definitions.
6	 *   2. Implements the first-run setup gate (redirects to /setup until KV flag is set).
7	 *   3. Handles Cloudflare Queues message batches (plugin job fanout).
8	 *   4. Handles Cloudflare Cron Triggers (heartbeat sweep, budget checks, DB backup).
9	 *   5. Re-exports all Durable Object and Workflow classes so Wrangler can
10	 *      register them — they must be named exports from the Worker's main module.
11	 */
12	
13	import { Hono } from "hono";
14	import { createHyperdriveDb } from "../db/hyperdrive.js";
15	import { R2Provider } from "../storage/r2-provider.js";
16	import { createSetupApp } from "./setup.js";
17	import { bootCloudflare } from "../boot.js";
18	
19	// ---------------------------------------------------------------------------
20	// Env — Cloudflare bindings injected at runtime
21	// ---------------------------------------------------------------------------
22	
23	export interface Env {
24	  // Databases
25	  HYPERDRIVE: { connectionString: string };
26	
27	  // Object storage
28	  PAPERCLIP_STORAGE: R2Bucket;
29	
30	  // KV — setup flags, hot config, session cache
31	  PAPERCLIP_KV: KVNamespace;
32	
33	  // Durable Object namespaces
34	  TASK_DO: DurableObjectNamespace;
35	  AGENT_RUN_DO: DurableObjectNamespace;
36	  SCHEDULER_DO: DurableObjectNamespace;
37	
38	  // Queues
39	  PAPERCLIP_QUEUE: Queue;
40	
41	  // Workflows
42	  HEARTBEAT_WORKFLOW: Workflow;
43	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
44	
45	  // Vars (set in wrangler.toml [vars])
46	  DEPLOYMENT_PLATFORM: string;
47	  DEPLOYMENT_MODE: string;
48	  DEPLOYMENT_EXPOSURE: string;
49	
50	  // Secrets (set via `wrangler secret put`)
51	  // MASTER_ENCRYPTION_KEY: string  — encrypts all other secrets stored in DB
52	  // SANDBOX_BRIDGE_URL: string
53	  // SANDBOX_BRIDGE_API_KEY: string
54	}
55	
56	// ---------------------------------------------------------------------------
57	// Hono app
58	// ---------------------------------------------------------------------------
59	
60	const app = new Hono<{ Bindings: Env }>();
61	
62	// Health check — always reachable, no auth, no setup gate
63	app.get("/api/health", (c) =>
64	  c.json({
65	    status: "ok",
66	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
67	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
68	    ts: new Date().toISOString(),
69	  }),
70	);
